namespace MTPR.Agent.Core.Models;

/// <summary>
/// Number of tokens consumed by a model call.
/// </summary>
/// <param name="PromptTokens">Tokens sent to the model.</param>
/// <param name="CompletionTokens">Tokens generated by the model.</param>
public sealed record TokenUsage(int PromptTokens, int CompletionTokens)
{
    /// <summary>
    /// Gets the sum of prompt and completion tokens.
    /// </summary>
    public int TotalTokens => PromptTokens + CompletionTokens;
}
